// Integrate-and-fire-or-burst (after Smith et al. 2000), dt in ms
// V: membrane (mV); h: availability of the T-type calcium current (0..1)
const p = { C: 2, gL: 0.035, EL: -65, gT: 0.07, ET: 120,
            Vh: -60, Vth: -35, Vreset: -50, tauMinus: 20, tauPlus: 100 };
function ifbStep(n, I, dt) {
  const iT = n.V >= p.Vh ? p.gT * n.h * (n.V - p.ET) : 0; // T-current flows above Vh
  n.V += dt * (I - p.gL * (n.V - p.EL) - iT) / p.C;
  // below Vh, h recovers slowly; above it, h inactivates faster
  n.h += dt * (n.V < p.Vh ? (1 - n.h) / p.tauPlus : -n.h / p.tauMinus);
  if (n.V >= p.Vth) { n.V = p.Vreset; return true; }
  return false;
}
